 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    mid = w // 2
    left = [row[:mid] for row in grid]
    right = [row[mid + 1:] for row in grid]

    def background(half):
        return Counter(value for row in half for value in row).most_common(1)[0][0]

    left_bg = background(left)
    right_bg = background(right)
    return [
        [2 if left[r][c] != left_bg or right[r][c] != right_bg else 3
         for c in range(mid)]
        for r in range(h)
    ]


